function applyState(state,message){E.data=state;if(!E.data.plots.some(function(p){return p.id===E.selected;}))E.selected='B2';drawCity();renderOwnerTags();updateHUD();if(message)toast(message);}
function fetchState(){var load=q('.estate-load');load.hidden=false;q('[data-estate-load-title]').textContent='同步16格城市';q('[data-estate-progress]').textContent='管理員沙盒';if(!E.ctx.api){applyState(demoState());load.hidden=true;return Promise.resolve();}return E.ctx.api('estateSandboxState',{}).then(function(r){applyState(r.state);load.hidden=true;},function(e){load.hidden=true;toast(e.message||'城市同步失敗',true);});}
function runAction(action,extra,after){if(E.busy)return Promise.resolve();E.busy=true;E.root.querySelectorAll('.estate-action,[data-build-upgrade],[data-build-collect]').forEach(function(b){b.disabled=true;});var data=Object.assign({action:action,lotId:E.selected},extra||{}),endpoint=(action==='collect'||action==='upgrade')?'adminEstateSandboxEconomy':'adminEstateSandboxAction',promise=E.ctx.api?E.ctx.api(endpoint,data):Promise.resolve({state:E.data,message:'離線視覺測試'});return promise.then(function(r){if(r.account){E.ctx.account=r.account;if(E.ctx.onAccount)E.ctx.onAccount(r.account);}if(after)after(r);else{applyState(r.state,r.message);if(action==='upgrade'&&E.mode==='city')upgradeCelebrate(lotPosition(E.selected));}return r;}).catch(function(e){toast(e.message||'操作失敗',true);}).finally(function(){E.busy=false;updateHUD();});}
function bindActionButtons(){E.root.querySelectorAll('[data-estate-act]').forEach(function(b){b.onclick=function(){var a=b.getAttribute('data-estate-act');if(a==='overview')overview();else if(a==='day')toggleDay();else if(a==='missile')attack(a);else runAction(a);};});}
function bind(){q('[data-estate-exit]').onclick=function(){if(E.ctx.onExit)E.ctx.onExit();};q('[data-estate-overview]').onclick=overview;q('[data-estate-market]').onclick=focusBlackMarket;E.root.querySelectorAll('[data-estate-mode]').forEach(function(b){b.onclick=function(){setMode(b.getAttribute('data-estate-mode'));};});var wheel=function(e){if(e.ctrlKey)e.preventDefault();},touch=function(e){if(e.touches&&e.touches.length>1)e.preventDefault();},gesture=function(e){e.preventDefault();};E.root.addEventListener('wheel',wheel,{passive:false});E.root.addEventListener('touchmove',touch,{passive:false});E.root.addEventListener('gesturestart',gesture,{passive:false});E.root.addEventListener('gesturechange',gesture,{passive:false});E.root.addEventListener('gestureend',gesture,{passive:false});E.lockHandlers={wheel:wheel,touch:touch,gesture:gesture};}

function bindCanvas(){var canvas=q('canvas'),down=null;canvas.addEventListener('pointerdown',function(e){down={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',function(e){if(!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>7){down=null;return;}down=null;var rect=canvas.getBoundingClientRect(),mouse=new T.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),ray=new T.Raycaster();ray.setFromCamera(mouse,E.camera);var hits=ray.intersectObjects((E.clickables||[]).concat(E.specialClickables||[]),false);if(!hits.length)return;var hit=hits[0].object;if(hit.userData.special==='blackmarket')focusBlackMarket();else if(hit.userData.lotId)selectLot(hit.userData.lotId,true);});}

function ringAt(pos,color,max,duration){var g=new T.RingGeometry(.3,.48,40),m=new T.MeshBasicMaterial({color:color,transparent:true,opacity:1,side:T.DoubleSide,depthWrite:false}),o=new T.Mesh(g,m);o.rotation.x=-Math.PI/2;o.position.copy(pos);o.position.y=.35;E.scene.add(o);E.fx.push({obj:o,start:performance.now(),duration:duration||900,update:function(t){o.scale.setScalar(1+max*t);m.opacity=1-t;}});}
function upgradeCelebrate(pos){ringAt(pos,0x6deeff,10,1300);ringAt(pos,0xbd86ff,7,1600);var center=pos.clone().add(new T.Vector3(0,2.2,0));particles(center,70,0x7eeaff,8,false);var light=new T.PointLight(0x72e8ff,12,28);light.position.copy(center);E.scene.add(light);E.fx.push({obj:new T.Group(),start:performance.now(),duration:1250,update:function(t){light.intensity=12*(1-t);},done:function(){E.scene.remove(light);}});E.shake=.36;}
function particles(pos,count,color,power,smoke){var group=new T.Group(),geo=new T.IcosahedronGeometry(smoke ? .18 : .1,0);for(var i=0;i<count;i++){var m=new T.MeshBasicMaterial({color:smoke?0x303943:color,transparent:true,opacity:smoke ? .48 : 1,depthWrite:false}),p=new T.Mesh(geo,m);p.position.copy(pos);p.userData.v=new T.Vector3((Math.random()-.5)*power,Math.random()*power*.85,(Math.random()-.5)*power);p.userData.smoke=!!smoke;group.add(p);}E.scene.add(group);E.fx.push({obj:group,start:performance.now(),duration:smoke?1900:1100,update:function(t,dt){group.children.forEach(function(p){p.position.addScaledVector(p.userData.v,dt);p.userData.v.y += p.userData.smoke ? .1 * dt : -7 * dt;p.scale.setScalar(p.userData.smoke?1+t*3:1+t*1.5);p.material.opacity=(p.userData.smoke ? .48 : 1)*(1-t);});}});}
function blast(pos,kind,result){var flash=q('.estate-flash'),center=pos.clone().add(new T.Vector3(0,3,0));if(result.defended){flash.style.transition='none';flash.style.background='#6ff4ff';flash.style.opacity='.42';requestAnimationFrame(function(){flash.style.transition='opacity .65s';flash.style.opacity='0';});ringAt(pos,0x75f4ff,13,1450);ringAt(pos,0xb68cff,9,1100);var shield=new T.Mesh(new T.SphereGeometry(4.6,28,18),new T.MeshBasicMaterial({color:0x65eaff,transparent:true,opacity:.38,wireframe:true,depthWrite:false}));shield.position.copy(center);E.scene.add(shield);E.fx.push({obj:shield,start:performance.now(),duration:1200,update:function(t){shield.scale.setScalar(.35+t*.9);shield.rotation.y+=.08;shield.material.opacity=.38*(1-t);}});E.shake=.55;applyState(result.state,result.message);return;}flash.style.transition='none';flash.style.background='#fff';flash.style.opacity='.9';requestAnimationFrame(function(){flash.style.transition='opacity .9s';flash.style.opacity='0';});ringAt(pos,0xff365f,16,1450);ringAt(pos,0xffd277,12,1050);var fire=new T.Mesh(new T.IcosahedronGeometry(1,3),new T.MeshBasicMaterial({color:0xff8438,transparent:true,opacity:1,depthWrite:false}));fire.position.copy(center);E.scene.add(fire);var light=new T.PointLight(0xff6a32,22,42);light.position.copy(center);E.scene.add(light);E.fx.push({obj:fire,start:performance.now(),duration:1550,update:function(t){var pulse=Math.sin(Math.PI*Math.min(1,t));fire.scale.setScalar(.35+8.4*pulse);fire.material.color.setHex(t<.3?0xffffff:t<.7?0xff7d32:0x54252c);fire.material.opacity=Math.max(0,1-t*.92);light.intensity=22*(1-t);},done:function(){E.scene.remove(light);}});particles(center,140,0xff9b4a,17,false);particles(center,42,0x303943,5.6,true);E.shake=1.8;applyState(result.state,result.message);}
function attack(kind){var target=currentPlot();if(!target)return;runAction('attack',{weapon:kind},function(result){launchWeapon(kind,lotPosition(target.id),function(){blast(lotPosition(target.id),kind,result);});});}
function launchWeapon(kind,target,done){ringAt(target,0xff315e,6,2050);
  var missile=new T.Group(),body=mat(0x39454d,.2,.9),nose=mat(0x65172b,.26,.66);add(missile,new T.CylinderGeometry(.3,.38,3.35,18),body,0,0,0);add(missile,new T.ConeGeometry(.38,.92,18),nose,0,2.12,0);[-1,1].forEach(function(side){var fin=add(missile,new T.BoxGeometry(.07,.72,.68),nose,side*.38,-1.28,0);fin.rotation.z=side*.28;});var flame=add(missile,new T.ConeGeometry(.35,1.9,14),new T.MeshBasicMaterial({color:0x65ecff,transparent:true,opacity:.95,depthWrite:false}),0,-2.58,0);add(missile,new T.ConeGeometry(.18,1.3,12),new T.MeshBasicMaterial({color:0xffffff,transparent:true,opacity:.9,depthWrite:false}),0,-2.5,0);missile.scale.setScalar(1);var from=new T.Vector3(E.camera.aspect<.8?2.4:5,3,-14),to=new T.Vector3(0,-1,-6.5);missile.position.copy(from);E.camera.add(missile);E.fx.push({obj:missile,start:performance.now(),duration:2050,keep:true,update:function(t){var p=from.clone().lerp(to,t),nt=Math.min(1,t+.014),next=from.clone().lerp(to,nt);p.y+=Math.sin(Math.PI*t)*.8;next.y+=Math.sin(Math.PI*nt)*.8;missile.position.copy(p);missile.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),next.clone().sub(p).normalize());flame.scale.y=.7+Math.random()*.65;if(Math.random()>.18){missile.updateMatrixWorld(true);var wp=missile.getWorldPosition(new T.Vector3()),tr=new T.Mesh(new T.SphereGeometry(.16,7,5),new T.MeshBasicMaterial({color:Math.random()>.55?0x66eaff:0xffa545,transparent:true,opacity:.82,depthWrite:false}));tr.position.copy(wp);E.scene.add(tr);E.fx.push({obj:tr,start:performance.now(),duration:760,update:function(k){tr.scale.setScalar(1+k*3.3);tr.material.opacity=.82*(1-k);}});}},done:function(){E.camera.remove(missile);disposeObject(missile);done();}});}

function toggleDay(){E.night=!E.night;toast(E.night?'已切換為夜間巡視':'已切換為日間巡視');updateHUD();}
function resize(){if(!E.root||!E.renderer)return;var r=E.root.getBoundingClientRect();if(!r.width||!r.height)return;E.camera.aspect=r.width/r.height;E.camera.updateProjectionMatrix();E.renderer.setSize(r.width,r.height,false);}
function updateLight(dt){var n=E.night?1:0;E.dayMix+=(n-E.dayMix)*Math.min(1,dt*2.4);var d=E.dayMix;E.scene.background.setRGB(.08*(1-d)+.004*d,.22*(1-d)+.009*d,.3*(1-d)+.027*d);E.scene.fog.color.copy(E.scene.background);E.hemi.intensity=1.65*(1-d)+.32*d;E.sun.intensity=2.8*(1-d)+.2*d;E.stars.material.opacity=d*.9;E.renderer.toneMappingExposure=1.32*(1-d)+.72*d;}
function frame(now){if(!E.active||E.disposed){E.raf=0;return;}E.raf=requestAnimationFrame(frame);var dt=Math.min(.05,(now-(E.last||now))/1000);E.last=now;E.controls.update();updateLight(dt);
  if(E.cameraTween){var c=E.cameraTween,t=Math.min(1,(now-c.start)/c.duration),k=1-Math.pow(1-t,3);E.camera.position.lerpVectors(c.fromP,c.toP,k);E.controls.target.lerpVectors(c.fromT,c.toT,k);if(t>=1){E.cameraTween=null;if(c.done)c.done();}}
  Object.keys(E.lots).forEach(function(id){var g=E.lots[id].group;if(!g)return;g.traverse(function(o){if(o.userData.spin)o.rotation.z+=dt*o.userData.spin;if(o.userData.pulse!=null&&o.material&&o.material.opacity!=null)o.material.opacity=.34+.22*Math.sin(now*.002+o.userData.pulse);});});
  if(E.model&&E.model.userData.reveal<1){E.model.userData.reveal=Math.min(1,E.model.userData.reveal+dt*1.9);var rv=E.model.userData.reveal,k2=.72+.28*(1-Math.pow(1-rv,3));E.model.scale.setScalar(E.model.userData.finalScale*k2);}
  for(var i=E.fx.length-1;i>=0;i--){var f=E.fx[i],tt=Math.min(1,(now-f.start)/f.duration);f.update(tt,dt);if(tt>=1){if(!f.keep){E.scene.remove(f.obj);disposeObject(f.obj);}if(f.done)f.done();E.fx.splice(i,1);}}
  if(E.preview&&E.mode==='build'){var pr=E.preview.canvas.getBoundingClientRect();if(pr.width&&pr.height&&(E.preview.canvas.width!==Math.round(pr.width*(Math.min(global.devicePixelRatio||1,1.5))))){E.preview.camera.aspect=pr.width/pr.height;E.preview.camera.updateProjectionMatrix();E.preview.renderer.setSize(pr.width,pr.height,false);}E.preview.controls.update();E.preview.ring.rotation.z+=dt*.18;E.preview.renderer.render(E.preview.scene,E.preview.camera);}updateOwnerTags();updateMarketTag();var original=E.camera.position.clone();if(E.shake>0){E.shake=Math.max(0,E.shake-dt*1.7);E.camera.position.x+=(Math.random()-.5)*E.shake;E.camera.position.y+=(Math.random()-.5)*E.shake;E.camera.position.z+=(Math.random()-.5)*E.shake;}E.renderer.render(E.scene,E.camera);if(E.shake>0)E.camera.position.copy(original);
}

function mount(root,ctx){if(!root)return;if(E.root===root&&!E.disposed){E.ctx=ctx;setActive(true);return;}unmount();addStyle();E.root=root;E.ctx=ctx;E.disposed=false;E.active=true;E.night=false;E.dayMix=0;E.focused=false;E.mode='city';E.selected='B2';E.previewLevel=1;root.innerHTML=markup(ctx);bind();initScene();fetchState();E.last=performance.now();E.raf=requestAnimationFrame(frame);}
function setActive(active){E.active=!!active;if(E.active&&!E.disposed&&!E.raf){E.last=performance.now();E.raf=requestAnimationFrame(frame);}if(!E.active&&E.raf){cancelAnimationFrame(E.raf);E.raf=0;}}
function unmount(){E.disposed=true;E.active=false;++E.token;disposePreview();if(E.raf)cancelAnimationFrame(E.raf);E.raf=0;E.timers.splice(0).forEach(clearTimeout);if(E.resize)E.resize.disconnect();if(E.controls)E.controls.dispose();if(E.scene)disposeObject(E.scene);if(E.renderer)E.renderer.dispose();if(E.root&&E.lockHandlers){E.root.removeEventListener('wheel',E.lockHandlers.wheel);E.root.removeEventListener('touchmove',E.lockHandlers.touch);E.root.removeEventListener('gesturestart',E.lockHandlers.gesture);E.root.removeEventListener('gesturechange',E.lockHandlers.gesture);E.root.removeEventListener('gestureend',E.lockHandlers.gesture);}if(E.root)E.root.innerHTML='';E.root=null;E.scene=null;E.model=null;E.data=null;E.fx=[];E.lots={};E.landmarks={};E.specialClickables=[];E.lockHandlers=null;}

global.EstateApp={mount:mount,setActive:setActive,unmount:unmount,stages:STAGES,focusLot:function(id){selectLot(id,true);},refresh:fetchState};
